import type {HandbookEntry} from './handbook-types';

type Row=[id:string,title:string,doc:string,description:string,syntax:string,example:string,notes:string,tokens?:string[]];
const api=(member:string)=>'https://learn.microsoft.com/ru-ru/dotnet/api/'+member;
const keyboard='https://learn.microsoft.com/en-us/visualstudio/ide/default-keyboard-shortcuts-in-visual-studio';
const methods='https://learn.microsoft.com/ru-ru/dotnet/csharp/programming-guide/classes-and-structs/methods';
const constructors='https://learn.microsoft.com/ru-ru/dotnet/csharp/programming-guide/classes-and-structs/constructors';
const properties='https://learn.microsoft.com/ru-ru/dotnet/csharp/programming-guide/classes-and-structs/properties';
const entries:HandbookEntry[]=[];
function add(category:string,kind:string,rows:Row[]){for(const [id,title,doc,description,syntax,example,notes,tokens] of rows)entries.push({id:'wf-'+id,title,category,kind,description,syntax,example,notes,docsUrl:doc.startsWith('https:')?doc:api(doc),lectureTokens:tokens??[title],aliases:tokens??[],language:category==='Visual Studio'?'text':'csharp'});}

add('Windows Forms','Элемент управления',[
 ['form','Form','system.windows.forms.form','Окно настольного приложения. В нём размещают элементы управления и обрабатывают действия пользователя.','class MyForm : Form','public partial class CatalogForm : Form\n{\n    public CatalogForm()\n    {\n        InitializeComponent();\n    }\n}','Класс формы наследует Form. Изменения интерфейса в учебном проекте вносите через конструктор Visual Studio.',['Form','форма','Form1']],
 ['button','Button','system.windows.forms.button','Кнопка запускает действие через событие Click. Её видимая надпись хранится в Text.','Button button = new Button();','Button button = new Button();\nbutton.Text = "Проверить";\nbutton.Click += (_, _) => MessageBox.Show("Нажато");\nControls.Add(button);','Создание кнопки и присваивание Text не создают автоматически нужный обработчик.',['Button']],
 ['label','Label','system.windows.forms.label','Надпись для заголовка, пояснения или результата. Пользователь обычно не редактирует её текст.','label.Text = "Результат";','lblOutput.Text = "Товар добавлен";\nlblOutput.AutoSize = true;','Для ввода нужен TextBox, а для вывода постоянной надписи — Label.',['Label']],
 ['textbox','TextBox','system.windows.forms.textbox','Поле для ввода текста. Даже введённое число сначала находится в свойстве Text как строка.','string text = textBox.Text;','string article = txtArticle.Text.Trim();\nlblOutput.Text = article;','Перед вычислениями преобразуйте текст через TryParse и проверьте допустимость значения.',['TextBox']],
 ['numeric','NumericUpDown','system.windows.forms.numericupdown','Поле числового ввода со стрелками. Value имеет тип decimal; диапазон задают Minimum и Maximum.','decimal value = numeric.Value;','nudStock.Minimum = 0;\nnudStock.Maximum = 10000;\nint stock = (int)nudStock.Value;','Приведение к int уместно для целого количества; DecimalPlaces у такого поля обычно равен 0.',['NumericUpDown']],
 ['combobox','ComboBox','system.windows.forms.combobox','Раскрывающийся список. Можно разрешить ввод текста или ограничить выбор готовыми вариантами.','comboBox.Items.Add(value);','cmbCategory.Items.Add("Кроссовки");\ncmbCategory.Items.Add("Сандалии");\ncmbCategory.DropDownStyle = ComboBoxStyle.DropDownList;','При DropDownList нельзя ввести произвольный текст; заранее заполните Items.',['ComboBox']],
 ['listbox','ListBox','system.windows.forms.listbox','Показывает список строк или объектов и позволяет выбирать элементы. В отличие от DataGridView не разбивает запись на колонки.','listBox.Items.Add(item);','lstCatalog.Items.Clear();\nlstCatalog.Items.Add("Кроссовки: 2 шт.");','Повторный вывод без Items.Clear() добавляет одинаковые строки.',['ListBox']],
 ['datagridview','DataGridView','system.windows.forms.datagridview','Таблица с колонками и строками. Может заполняться вручную или отображать привязанный источник данных.','dataGridView.Rows.Add(values);','dgvProducts.Columns.Add("Name", "Товар");\ndgvProducts.Columns.Add("Stock", "Остаток");\ndgvProducts.Rows.Add("Кроссовки", 2);','Не смешивайте бесконтрольно ручное Rows.Add и режим с DataSource.',['DataGridView']],
 ['panel','Panel','system.windows.forms.panel','Контейнер для группы элементов. Помогает управлять их расположением и видимостью вместе.','panel.Controls.Add(control);','Panel panel = new Panel();\npanel.Dock = DockStyle.Bottom;\npanel.Height = 60;\nControls.Add(panel);','Свойства координат дочернего элемента отсчитываются от его контейнера.',['Panel']],
 ['groupbox','GroupBox','system.windows.forms.groupbox','Контейнер с заголовком для смысловой группы полей. RadioButton внутри одной группы работают как взаимно исключающий выбор.','groupBox.Text = "Параметры";','groupBox1.Text = "Данные товара";\ngroupBox1.Controls.Add(textBox1);','Отдельные группы RadioButton помещайте в разные контейнеры.',['GroupBox']],
 ['checkbox','CheckBox','system.windows.forms.checkbox','Элемент выбора «да/нет». Состояние обычно читается через Checked.','bool enabled = checkBox.Checked;','if (chkDiscount.Checked)\n    nudDiscount.Value = 10;','Text — подпись, Checked — состояние; это разные свойства.',['CheckBox']],
 ['radiobutton','RadioButton','system.windows.forms.radiobutton','Один вариант из группы взаимоисключающих вариантов. Состояние выбранного пункта задаёт Checked.','radioButton.Checked','if (radioRetail.Checked)\n    lblOutput.Text = "Розничный покупатель";','RadioButton группируются по родительскому контейнеру, а не по похожим именам.',['RadioButton']],
 ['datetimepicker','DateTimePicker','system.windows.forms.datetimepicker','Поле выбора даты и времени. Числовые вычисления с датой делайте через Value, а не через показанный текст.','DateTime date = datePicker.Value;','DateTime date = dateTimePicker1.Value.Date;\nlblOutput.Text = date.ToString("dd.MM.yyyy");','Показанная пользователю строка зависит от формата и региональных настроек.',['DateTimePicker']],
 ['picturebox','PictureBox','system.windows.forms.picturebox','Элемент для изображения. Способ размещения картинки определяется SizeMode.','pictureBox.SizeMode = PictureBoxSizeMode.Zoom;','pictureBox1.SizeMode = PictureBoxSizeMode.Zoom;\npictureBox1.Image = Image.FromFile("product.png");','Освобождайте Image, когда она больше не нужна. FromFile может удерживать файл открытым до Dispose изображения.',['PictureBox']],
 ['tablelayout','TableLayoutPanel','system.windows.forms.tablelayoutpanel','Контейнер раскладки по строкам и столбцам. Удобен для формы с подписями и полями разных размеров.','table.Controls.Add(control, column, row);','tableLayoutPanel1.ColumnCount = 2;\ntableLayoutPanel1.Controls.Add(lblTitle, 0, 0);','Столбцы и строки контейнера — раскладка интерфейса, а не записи DataGridView.',['TableLayoutPanel']],
 ['flowlayout','FlowLayoutPanel','system.windows.forms.flowlayoutpanel','Размещает дочерние элементы последовательно и при настройке переносит их на следующую строку.','flowPanel.FlowDirection = FlowDirection.LeftToRight;','flowLayoutPanel1.WrapContents = true;\nflowLayoutPanel1.Controls.Add(btnTotal);','Подходит для ряда кнопок; точную сетку полей удобнее делать через TableLayoutPanel.',['FlowLayoutPanel']],
 ['errorprovider','ErrorProvider','system.windows.forms.errorprovider','Показывает значок ошибки рядом с конкретным полем, не прерывая работу отдельным MessageBox.','errorProvider.SetError(control, message);','errorProvider1.SetError(txtProductName,\n    string.IsNullOrWhiteSpace(txtProductName.Text)\n        ? "Введите название" : "");','Пустая строка убирает ошибку у поля. Для компонента укажите ContainerControl формы.',['ErrorProvider']],
 ['bindingsource','BindingSource','system.windows.forms.bindingsource','Промежуточный источник для привязки данных к интерфейсу. Управляет текущим элементом и уведомлениями для связанных компонентов.','bindingSource.DataSource = data;','BindingSource source = new BindingSource();\nsource.DataSource = products;\ndgvProducts.DataSource = source;','Обычный List<T> не уведомляет интерфейс обо всех изменениях; для динамических данных часто нужен BindingList<T>.',['BindingSource']],
 ['timer','System.Windows.Forms.Timer','system.windows.forms.timer','Вызывает Tick в потоке интерфейса через заданные интервалы. Подходит для небольших периодических обновлений окна.','timer.Interval = milliseconds;','timer1.Interval = 1000;\ntimer1.Tick += (_, _) => lblOutput.Text = DateTime.Now.ToString("T");\ntimer1.Start();','Долгая работа в Tick блокирует окно. Это не точный таймер реального времени.',['System.Windows.Forms.Timer','Tick']]
]);

add('Свойства интерфейса','Свойство',[
 ['name','Control.Name','system.windows.forms.control.name','Имя элемента, по которому к нему обращаются в коде и инструментах конструктора.','control.Name = "name";','btnStart.Name = "btnStart";','Изменение Text не переименовывает поле btnStart в исходном коде.',['Name']],
 ['text','Control.Text','system.windows.forms.control.text','Видимый текст элемента: заголовок формы, подпись кнопки, содержимое поля или надпись результата.','control.Text = value;','lblOutput.Text = "Здесь появится результат";\nbtnStart.Text = "Запустить";','Text возвращает строку; для чисел нужен разбор или форматирование.',['Text']],
 ['backcolor','Control.BackColor','system.windows.forms.control.backcolor','Цвет фона элемента. Часто используется для состояния ошибки или предупреждения.','control.BackColor = color;','lblStock.BackColor = Color.MistyRose;','После исправления данных верните обычный фон, иначе сохранится старое предупреждение.',['Control.BackColor','Form.BackColor','lblStock.BackColor','BackColor (цвет фона)']],
 ['forecolor','Control.ForeColor','system.windows.forms.control.forecolor','Цвет текста и других передних элементов отрисовки компонента.','control.ForeColor = color;','lblStock.ForeColor = Color.DarkRed;','Обеспечивайте читаемый контраст с BackColor.',['Control.ForeColor','Form.ForeColor','Label.ForeColor','lblStock.ForeColor']],
 ['font','Control.Font','system.windows.forms.control.font','Шрифт элемента: семейство, размер и начертание.','control.Font = new Font(family, size, style);','lblTitle.Font = new Font("Segoe UI", 18F, FontStyle.Bold);','Крупный шрифт может требовать AutoSize или большего Size; в учебном проекте Font удобно менять через F4.',['Font']],
 ['autosize','Control.AutoSize','system.windows.forms.control.autosize','Разрешает элементу автоматически подбирать размер по содержимому. Поведение зависит от типа компонента.','control.AutoSize = true;','lblTitle.AutoSize = true;','Это не универсальное масштабирование всей формы; у разных компонентов правила различаются.',['AutoSize']],
 ['location','Control.Location','system.windows.forms.control.location','Координаты верхнего левого угла элемента относительно клиентской области родителя.','control.Location = new Point(x, y);','btnStart.Location = new Point(24, 100);','Координаты отсчитываются не обязательно от всей формы: элемент может находиться внутри Panel.',['Location']],
 ['size','Control.Size','system.windows.forms.control.size','Ширина и высота элемента. Для размера клиентской области формы есть отдельное ClientSize.','control.Size = new Size(width, height);','txtProductName.Size = new Size(240, 28);','Не путайте Size с Location: первое задаёт размер, второе — положение.',['Size']],
 ['clientsize','Form.ClientSize','system.windows.forms.form.clientsize','Размер внутренней области окна без внешней рамки и заголовка.','ClientSize = new Size(width, height);','ClientSize = new Size(900, 600);','Если рассчитываете размещение полей вручную, ориентируйтесь на клиентскую область.',['ClientSize']],
 ['width-height','Control.Width и Height','system.windows.forms.control.width','Позволяют менять ширину и высоту по отдельности вместо установки всего Size.','control.Width = width;\ncontrol.Height = height;','txtProductName.Width = 260;\nbtnStart.Height = 36;','AutoSize, Dock и контейнер раскладки могут влиять на итоговые размеры.',['Width','Height']],
 ['dock','Control.Dock','system.windows.forms.control.dock','Прикрепляет элемент к краю родителя или заполняет оставшуюся область.','control.Dock = DockStyle.Fill;','dgvProducts.Dock = DockStyle.Fill;','При нескольких закреплённых элементах важен порядок в Controls.',['Dock','DockStyle']],
 ['anchor','Control.Anchor','system.windows.forms.control.anchor','Сохраняет расстояние до выбранных краёв контейнера при изменении его размера.','control.Anchor = AnchorStyles.Top | AnchorStyles.Right;','txtProductName.Anchor = AnchorStyles.Top |\n    AnchorStyles.Left | AnchorStyles.Right;','Привязка к левому и правому краям заставляет поле растягиваться по ширине.',['Anchor','AnchorStyles']],
 ['enabled','Control.Enabled','system.windows.forms.control.enabled','Разрешает или запрещает взаимодействие с элементом.','control.Enabled = condition;','btnTotal.Enabled = nudQuantity.Value > 0;','Отключённая кнопка не заменяет проверку входных данных внутри обработчика.',['Enabled']],
 ['visible','Control.Visible','system.windows.forms.control.visible','Определяет, показывается ли элемент пользователю.','control.Visible = true;','lblValidation.Visible = true;','Если скрыт родитель, дочерний элемент не виден даже при собственном Visible = true.',['Visible']],
 ['tabindex','Control.TabIndex','system.windows.forms.control.tabindex','Порядок перемещения фокуса клавишей Tab внутри контейнера.','control.TabIndex = index;','txtProductName.TabIndex = 0;\ntxtManufacturer.TabIndex = 1;','Номера относятся к одному контейнеру. Проверьте форму клавиатурой.',['TabIndex']],
 ['tag','Control.Tag','system.windows.forms.control.tag','Произвольный объект, связанный с компонентом. Аналогичное Tag есть у строки DataGridView.','control.Tag = object;','btnDetails.Tag = selectedProduct;','Тип Tag — object. Перед использованием проверьте тип через is, а не считайте значение заведомо правильным.',['Control.Tag','Button.Tag','btnDetails.Tag']],
 ['controls-add','Controls.Add()','system.windows.forms.control.controlcollection.add','Добавляет элемент в коллекцию дочерних компонентов контейнера.','parent.Controls.Add(child);','Label caption = new Label { Text = "Название", AutoSize = true };\nControls.Add(caption);','В формах из методичек элементы обычно уже созданы конструктором; не добавляйте вторые копии.',['Controls.Add','Controls']],
 ['padding','Control.Padding','system.windows.forms.control.padding','Внутренние отступы контейнера или элемента.','control.Padding = new Padding(size);','panel1.Padding = new Padding(16);','Внешний промежуток между соседними элементами задаёт Margin.',['Padding']],
 ['margin','Control.Margin','system.windows.forms.control.margin','Внешний отступ, который учитывают контейнеры раскладки.','control.Margin = new Padding(size);','btnStart.Margin = new Padding(8);','При ручном размещении через Location Margin сам по себе не раздвигает соседние элементы.',['Margin']],
 ['focus','Control.Focus()','system.windows.forms.control.focus','Пытается передать фокус ввода элементу. Возвращает bool, сообщающий об успехе.','bool focused = control.Focus();','txtProductName.Focus();','Элемент должен быть доступен для фокуса: видим, включён и расположен на подходящем окне.',['Focus']],
 ['refresh','Control.Refresh()','system.windows.forms.control.refresh','Перерисовывает элемент и его дочерние элементы немедленно.','control.Refresh();','panel1.Refresh();','Не перечитывает список товаров и не заменяет ваш RefreshProductsTable().',['Refresh']],
 ['invalidate','Control.Invalidate()','system.windows.forms.control.invalidate','Помечает область как требующую перерисовки при следующем цикле сообщений.','control.Invalidate();','pictureBox1.Invalidate();','Обычно подходит для пользовательского рисования; не делает синхронное обновление данных.',['Invalidate']]
]);

add('Поля и списки','Свойство или метод',[
 ['clear','TextBox.Clear()','system.windows.forms.textboxbase.clear','Очищает содержимое текстового поля.','textBox.Clear();','txtProductName.Clear();\ntxtManufacturer.Clear();','Очищайте поля после успешной операции; при ошибке сохраните ввод для исправления.',['TextBox.Clear','txtProductName.Clear','txtManufacturer.Clear','txtNewName.Clear','txtNewManufacturer.Clear','txtNewPrice.Clear','txtNewStock.Clear']],
 ['appendtext','TextBox.AppendText()','system.windows.forms.textboxbase.appendtext','Добавляет текст в конец существующего содержимого поля.','textBox.AppendText(text);','txtLog.AppendText("Товар добавлен" + Environment.NewLine);','Для журнала включите Multiline. Это операция интерфейса, а не запись файла на диск.',['AppendText']],
 ['selectall','TextBox.SelectAll()','system.windows.forms.textboxbase.selectall','Выделяет весь текст поля, например чтобы быстро заменить ошибочное значение.','textBox.SelectAll();','txtArticle.Focus();\ntxtArticle.SelectAll();','SelectAll не очищает поле: пользователь может скопировать или заменить выделение.',['SelectAll']],
 ['multiline','TextBox.Multiline','system.windows.forms.textbox.multiline','Разрешает несколько строк текста в одном TextBox.','textBox.Multiline = true;','txtLog.Multiline = true;\ntxtLog.ScrollBars = ScrollBars.Vertical;','Высоту поля и полосы прокрутки нужно настроить отдельно.',['Multiline']],
 ['textbox-readonly','TextBox.ReadOnly','system.windows.forms.textboxbase.readonly','Запрещает редактирование текста пользователем, сохраняя возможность выделять и копировать его.','textBox.ReadOnly = true;','txtReport.ReadOnly = true;','Программа всё ещё может изменить Text; это не защита данных от кода.',['TextBox.ReadOnly','txtReport.ReadOnly','txtLog.ReadOnly','txtProductName.ReadOnly']],
 ['maxlength','TextBox.MaxLength','system.windows.forms.textboxbase.maxlength','Ограничивает длину текста, который вводит пользователь.','textBox.MaxLength = length;','txtArticle.MaxLength = 30;','Ограничение пользовательского ввода не заменяет проверку длины строк, полученных из файла или присвоенных программно.',['MaxLength']],
 ['password','TextBox.UseSystemPasswordChar','system.windows.forms.textbox.usesystempasswordchar','Маскирует символы пароля при отображении в поле.','textBox.UseSystemPasswordChar = true;','txtPassword.UseSystemPasswordChar = true;','Маска не шифрует Text и не делает хранение пароля безопасным.',['UseSystemPasswordChar']],
 ['value','NumericUpDown.Value','system.windows.forms.numericupdown.value','Текущее числовое значение типа decimal.','decimal value = numeric.Value;','decimal price = nudPrice.Value;\nint quantity = (int)nudQuantity.Value;','Присваиваемое значение должно попадать между Minimum и Maximum.',['Value']],
 ['minimum','NumericUpDown.Minimum','system.windows.forms.numericupdown.minimum','Нижняя граница допустимого значения числового поля.','numeric.Minimum = value;','nudStock.Minimum = 0;','Для заказа обычно требуется больше 0, а для складского остатка допустим 0: это разные правила.',['Minimum']],
 ['maximum','NumericUpDown.Maximum','system.windows.forms.numericupdown.maximum','Верхняя граница допустимого значения числового поля.','numeric.Maximum = value;','nudStock.Maximum = 10000;','Перед nudStock.Value = stock проверяйте, что введённый stock не превышает эту границу.',['Maximum']],
 ['decimalplaces','NumericUpDown.DecimalPlaces','system.windows.forms.numericupdown.decimalplaces','Количество отображаемых десятичных разрядов.','numeric.DecimalPlaces = count;','nudPrice.DecimalPlaces = 2;\nnudQuantity.DecimalPlaces = 0;','Это настройка числового поля; денежные вычисления и окончательное округление определяются кодом.',['DecimalPlaces']],
 ['increment','NumericUpDown.Increment','system.windows.forms.numericupdown.increment','Шаг изменения значения стрелками поля.','numeric.Increment = step;','nudPrice.Increment = 0.50m;','Пользователь может набрать значение вручную; шаг не заменяет проверку предметных ограничений.',['Increment']],
 ['combo-items-add','ComboBox.Items.Add()','system.windows.forms.combobox.objectcollection.add','Добавляет вариант в раскрывающийся список.','comboBox.Items.Add(item);','cmbCategory.Items.Add("Сандалии");','Заполняйте варианты один раз или сначала очищайте Items, чтобы не получить дубликаты.',['ComboBox.Items.Add','cmbCategory.Items.Add']],
 ['selectedindex','ComboBox.SelectedIndex','system.windows.forms.combobox.selectedindex','Индекс выбранного элемента, начиная с 0. Значение -1 означает отсутствие выбора.','int index = comboBox.SelectedIndex;','if (cmbCategory.SelectedIndex < 0)\n    lblOutput.Text = "Выберите категорию";','Не обращайтесь по индексу -1 к Items.',['ComboBox.SelectedIndex','cmbCategory.SelectedIndex']],
 ['selecteditem','ComboBox.SelectedItem','system.windows.forms.combobox.selecteditem','Возвращает выбранный объект или null, если ничего не выбрано.','object? item = comboBox.SelectedItem;','string? category = cmbCategory.SelectedItem?.ToString();','Объект не всегда является строкой: список может содержать экземпляры вашего класса.',['ComboBox.SelectedItem','cmbCategory.SelectedItem']],
 ['dropdownstyle','ComboBox.DropDownStyle','system.windows.forms.combobox.dropdownstyle','Определяет, разрешён ли свободный текст или нужен выбор из списка.','comboBox.DropDownStyle = ComboBoxStyle.DropDownList;','cmbCategory.DropDownStyle = ComboBoxStyle.DropDownList;','Для выбора категории из фиксированного набора подходит DropDownList.',['DropDownStyle','DropDownList']],
 ['items-clear','ListBox.Items.Clear()','system.windows.forms.listbox.objectcollection.clear','Удаляет все отображаемые элементы ListBox.','listBox.Items.Clear();','lstCatalog.Items.Clear();\nforeach (Product item in _products)\n    lstCatalog.Items.Add(item.Name);','Удаление видимых строк не очищает автоматически вашу коллекцию _products.',['Items.Clear']],
 ['items-addrange','ListBox.Items.AddRange()','system.windows.forms.listbox.objectcollection.addrange','Добавляет сразу несколько элементов списка.','listBox.Items.AddRange(items);','lstProducts.Items.AddRange(new object[]\n{\n    "Кроссовки", "Ботинки", "Сандалии"\n});','При повторном заполнении сначала вызовите Items.Clear(), если старые строки не нужны.',['ListBox.Items.AddRange','lstProducts.Items.AddRange','lstCatalog.Items.AddRange']],
 ['list-selecteditem','ListBox.SelectedItem','system.windows.forms.listbox.selecteditem','Текущий выбранный объект ListBox. Если выбора нет, возвращается null.','object? item = listBox.SelectedItem;','if (lstCatalog.SelectedItem is string name)\n    lblOutput.Text = name;','При разрешённом множественном выборе используйте SelectedItems для всей группы.',['ListBox.SelectedItem','lstCatalog.SelectedItem','lstProducts.SelectedItem','lstCatalog.SelectedItems','lstProducts.SelectedItems']],
 ['performclick','Button.PerformClick()','system.windows.forms.button.performclick','Инициирует действие кнопки программно, если кнопка может быть выбрана.','button.PerformClick();','nudDiscount.Value = 0;\nbtnTotal.PerformClick();','Для большой программы общую логику удобнее вынести в отдельный метод, а не вызывать обработчики друг из друга.',['PerformClick']]
]);

add('Окна и события','Свойство или метод',[
 ['initializecomponent','InitializeComponent()','https://learn.microsoft.com/en-us/dotnet/desktop/winforms/controls-design/designer-overview','Метод, создаваемый конструктором Visual Studio, настраивает компоненты формы и их связи с событиями.','InitializeComponent();','public CatalogForm()\n{\n    InitializeComponent();\n    Text = "Каталог товаров";\n}','Это метод вашего сгенерированного partial-класса, а не универсальный метод любого объекта .NET. Вызов должен предшествовать обращению к полям элементов.',['InitializeComponent']],
 ['startposition','Form.StartPosition','system.windows.forms.form.startposition','Определяет начальное размещение окна при показе.','StartPosition = FormStartPosition.CenterScreen;','StartPosition = FormStartPosition.CenterScreen;','Это начальная позиция, а не постоянная фиксация окна по центру.',['StartPosition','CenterScreen']],
 ['show','Form.Show()','system.windows.forms.form.show','Показывает немодальное окно; пользователь может продолжать работать с другими окнами приложения.','form.Show();','ProductDetailsForm details = new ProductDetailsForm(selected);\ndetails.Show(this);','Не уничтожайте форму сразу после Show(), иначе окно закроется. Для using обычно выбирают модальный ShowDialog().',['Form.Show(','details.Show(','ShowDialog отличается от Show']],
 ['showdialog','Form.ShowDialog()','system.windows.forms.form.showdialog','Открывает модальное окно и возвращает DialogResult после его закрытия. Выполнение вызывающего метода ждёт окончания диалога.','DialogResult result = form.ShowDialog(owner);','using ProductDetailsForm details = new ProductDetailsForm(selected);\ndetails.ShowDialog(this);','Переданный selected должен быть объектом выбранной строки. Модальную форму после использования освобождают через Dispose/using.',['ShowDialog']],
 ['close','Form.Close()','system.windows.forms.form.close','Закрывает текущее окно. Для главной формы это обычно завершает цикл приложения.','Close();','private void btnClose_Click(object sender, EventArgs e)\n{\n    Close();\n}','Кнопка закрытия карточки должна вызывать Close() в самой карточке, а не в окне каталога.',['Close']],
 ['dispose','Control.Dispose()','system.windows.forms.control.dispose','Освобождает ресурсы компонента и его дочерних компонентов. Используется также через using.','control.Dispose();','using ProductDetailsForm details = new ProductDetailsForm(selected);\ndetails.ShowDialog(this);','Dispose — освобождение ресурсов, а не удаление класса или данных товара.',['Dispose']],
 ['dialogresult','Form.DialogResult','system.windows.forms.form.dialogresult','Результат модального диалога: OK, Cancel и другие значения.','DialogResult = DialogResult.OK;','if (dialog.ShowDialog(this) == DialogResult.OK)\n    lblOutput.Text = "Подтверждено";','Установка результата у модальной формы завершает диалог; значение None означает отсутствие окончательного результата.',['Form.DialogResult','DialogResult = DialogResult.']],
 ['acceptbutton','Form.AcceptButton','system.windows.forms.form.acceptbutton','Кнопка формы, связанная с клавишей Enter.','AcceptButton = button;','AcceptButton = btnTotal;','Многострочные поля и фокус других компонентов могут обрабатывать клавишу по собственным правилам.',['AcceptButton']],
 ['cancelbutton','Form.CancelButton','system.windows.forms.form.cancelbutton','Кнопка формы, связанная с клавишей Escape.','CancelButton = button;','CancelButton = btnClose;','Для предсказуемого результата диалога настройте также Button.DialogResult или обработчик Click.',['CancelButton']],
 ['click-event','Click','system.windows.forms.control.click','Событие нажатия на элемент. Обработчик описывает, что произойдёт в ответ.','button.Click += handler;','private void btnStart_Click(object sender, EventArgs e)\n{\n    lblOutput.Text = "Приложение работает!";\n}','Созданный метод не вызывается от кнопки, пока он не связан с Click через конструктор или +=.',['Click']],
 ['load-event','Form.Load','system.windows.forms.form.load','Возникает перед первым показом формы. Подходит для начального заполнения интерфейса.','Load += Form_Load;','private void CatalogForm_Load(object sender, EventArgs e)\n{\n    RefreshProductsTable();\n}','Данные нужно создать до их первого отображения; не добавляйте повторно тот же обработчик при каждом показе окна.',['Load']],
 ['shown-event','Form.Shown','system.windows.forms.form.shown','Возникает при первом отображении формы. Может использоваться для действий после её начального появления.','Shown += Form_Shown;','Shown += (_, _) => txtProductName.Focus();','Load и Shown — разные моменты жизненного цикла окна.',['Shown']],
 ['formclosing','Form.FormClosing','system.windows.forms.form.formclosing','Позволяет обработать закрытие формы и при необходимости отменить его через e.Cancel.','FormClosing += handler;','private void Form1_FormClosing(object sender, FormClosingEventArgs e)\n{\n    if (hasUnsavedChanges) e.Cancel = true;\n}','hasUnsavedChanges в примере — ваше поле bool. Не отменяйте закрытие без понятного способа сохранить или отказаться от изменений.',['FormClosing']],
 ['textchanged','TextBox.TextChanged','system.windows.forms.control.textchanged','Возникает при изменении Text, в том числе когда текст меняет программа.','textBox.TextChanged += handler;','txtProductName.TextChanged += (_, _) =>\n    lblOutput.Text = "Данные изменены";','Если внутри обработчика снова менять Text, можно получить повторный вызов события.',['TextChanged']],
 ['selectedindexchanged','ComboBox.SelectedIndexChanged','system.windows.forms.combobox.selectedindexchanged','Возникает при изменении выбранного индекса списка.','comboBox.SelectedIndexChanged += handler;','cmbCategory.SelectedIndexChanged += (_, _) =>\n    lblOutput.Text = cmbCategory.Text;','Событие может возникнуть при программном заполнении/выборе. Обработайте состояние SelectedIndex == -1.',['SelectedIndexChanged']],
 ['valuechanged','NumericUpDown.ValueChanged','system.windows.forms.numericupdown.valuechanged','Возникает при изменении числового значения. Можно использовать для пересчёта результата.','numeric.ValueChanged += handler;','nudQuantity.ValueChanged += (_, _) =>\n    lblOutput.Text = $"Количество: {nudQuantity.Value}";','Программное присваивание Value также может вызвать это событие.',['ValueChanged']],
 ['invoke','Control.Invoke()','system.windows.forms.control.invoke','Синхронно выполняет делегат в потоке, которому принадлежит компонент.','control.Invoke(action);','lblOutput.Invoke((Action)(() =>\n    lblOutput.Text = "Расчёт завершён"));','Используется при обновлении UI из фонового потока. Не обращайтесь к контролам напрямую из Task.Run и не отключайте проверку потоков ради обхода ошибки.',['Invoke']],
 ['invokeasync','Control.InvokeAsync()','system.windows.forms.control.invokeasync','Асинхронно отправляет действие в поток интерфейса и позволяет дождаться его через await.','await control.InvokeAsync(action);','await lblOutput.InvokeAsync(() =>\n    lblOutput.Text = "Готово");','Доступно начиная с .NET 9. Для проекта на .NET 8 используйте подходящие Invoke/BeginInvoke или возвращение в UI-контекст после await.',['InvokeAsync']]
]);

add('Таблица DataGridView','Свойство или метод',[
 ['columns-add','DataGridView.Columns.Add()','system.windows.forms.datagridviewcolumncollection.add','Создаёт колонку таблицы. В простом варианте первый аргумент — внутреннее имя, второй — видимый заголовок.','grid.Columns.Add(name, headerText);','dgvProducts.Columns.Add("OriginalPrice", "Начальная цена");','Добавлять колонки перед каждым обновлением без очистки нельзя: появятся дубликаты.',['Columns.Add']],
 ['columns-clear','DataGridView.Columns.Clear()','system.windows.forms.datagridviewcolumncollection.clear','Удаляет все колонки таблицы.','grid.Columns.Clear();','dgvProducts.Columns.Clear();\ndgvProducts.Columns.Add("Name", "Товар");','При перестройке таблицы определите, где создаются колонки: один раз в конструкторе или целиком в методе обновления.',['Columns.Clear']],
 ['rows-add','DataGridView.Rows.Add()','system.windows.forms.datagridviewrowcollection.add','Добавляет строку и возвращает её индекс. Порядок значений должен соответствовать колонкам.','int index = grid.Rows.Add(values);','int index = dgvProducts.Rows.Add(item.Name, item.Stock);\ndgvProducts.Rows[index].Tag = item;','Этот способ рассчитан на вручную заполняемую таблицу; при привязке меняют источник данных.',['Rows.Add']],
 ['rows-clear','DataGridView.Rows.Clear()','system.windows.forms.datagridviewrowcollection.clear','Очищает строки вручную заполняемой таблицы перед повторным выводом.','grid.Rows.Clear();','dgvProducts.Rows.Clear();\nforeach (Product item in _products)\n    dgvProducts.Rows.Add(item.Name, item.Stock);','Это не удаление товаров из _products. При DataSource очищайте подходящий источник данных.',['Rows.Clear']],
 ['rows-removeat','DataGridView.Rows.RemoveAt()','system.windows.forms.datagridviewrowcollection.removeat','Удаляет строку вручную заполненной таблицы по индексу.','grid.Rows.RemoveAt(index);','if (dgvProducts.CurrentRow is DataGridViewRow row && !row.IsNewRow)\n    dgvProducts.Rows.RemoveAt(row.Index);','Удаление отображаемой строки не обязательно удаляет объект из вашей коллекции; согласуйте данные и интерфейс.',['Rows.RemoveAt']],
 ['row','DataGridViewRow','system.windows.forms.datagridviewrow','Объект одной строки таблицы. Содержит ячейки, Tag и оформление строки.','DataGridViewRow row = grid.Rows[index];','DataGridViewRow row = dgvProducts.Rows[index];\nrow.Tag = item;','Строка интерфейса и Product — два разных объекта. Tag связывает их в учебном проекте.',['DataGridViewRow']],
 ['cells','DataGridViewRow.Cells','system.windows.forms.datagridviewrow.cells','Коллекция ячеек строки. Доступна по индексу или имени колонки.','row.Cells[columnName].Value','dgvProducts.Rows[0].Cells["Stock"].Value = 5;','Проверяйте наличие строки и имя колонки. Значение ячейки имеет тип object.',['Cells']],
 ['currentrow','DataGridView.CurrentRow','system.windows.forms.datagridview.currentrow','Строка, содержащая текущую ячейку. Может отсутствовать, например в пустой таблице.','DataGridViewRow? row = grid.CurrentRow;','if (dgvProducts.CurrentRow?.Tag is Product selected)\n    lblSelectedProduct.Text = selected.Name;','Не обращайтесь к CurrentRow.Tag без проверки null.',['CurrentRow']],
 ['selectedrows','DataGridView.SelectedRows','system.windows.forms.datagridview.selectedrows','Коллекция строк, выделенных пользователем. Её наполнение зависит от режима выделения.','grid.SelectedRows.Count','if (dgvProducts.SelectedRows.Count > 0)\n    lblOutput.Text = "Строка выделена";','Для выбора строк обычно нужен FullRowSelect; выбранная ячейка и выделенная строка не всегда одно и то же.',['SelectedRows']],
 ['selectionmode','DataGridView.SelectionMode','system.windows.forms.datagridview.selectionmode','Определяет, выделяются отдельные ячейки, строки или столбцы.','grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect;','dgvProducts.SelectionMode = DataGridViewSelectionMode.FullRowSelect;','Для карточки товара удобен выбор целой строки, а не произвольной ячейки.',['SelectionMode','FullRowSelect']],
 ['multiselect','DataGridView.MultiSelect','system.windows.forms.datagridview.multiselect','Разрешает или запрещает одновременное выделение нескольких элементов таблицы.','grid.MultiSelect = false;','dgvProducts.MultiSelect = false;','Не отменяет проверку наличия текущего товара перед открытием карточки.',['MultiSelect']],
 ['grid-readonly','DataGridView.ReadOnly','system.windows.forms.datagridview.readonly','Запрещает редактирование ячеек пользователем. Используется для таблицы-витрины.','grid.ReadOnly = true;','dgvProducts.ReadOnly = true;','Кнопки и методы всё ещё могут менять исходные товары и обновлять таблицу.',['ReadOnly']],
 ['allowaddrows','DataGridView.AllowUserToAddRows','system.windows.forms.datagridview.allowusertoaddrows','Управляет показом дополнительной строки для ручного ввода новой записи.','grid.AllowUserToAddRows = false;','dgvProducts.AllowUserToAddRows = false;','Лишняя пустая строка внизу часто появляется именно из-за этого свойства.',['AllowUserToAddRows']],
 ['autosizecolumns','DataGridView.AutoSizeColumnsMode','system.windows.forms.datagridview.autosizecolumnsmode','Задаёт общий способ автоматического подбора ширины колонок.','grid.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;','dgvProducts.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;','Fill распределяет доступную ширину. Длинные заголовки всё равно нужно проверять на читаемость.',['AutoSizeColumnsMode']],
 ['rowheaders','DataGridView.RowHeadersVisible','system.windows.forms.datagridview.rowheadersvisible','Показывает или скрывает служебную колонку заголовков строк слева.','grid.RowHeadersVisible = false;','dgvProducts.RowHeadersVisible = false;','Скрытие заголовков не изменяет количество колонок с данными.',['RowHeadersVisible']],
 ['defaultcellstyle','DataGridViewRow.DefaultCellStyle','system.windows.forms.datagridviewrow.defaultcellstyle','Стиль ячеек строки: фон, текст, формат и другие параметры отображения.','row.DefaultCellStyle.BackColor = color;','if (item.IsLowStock())\n    row.DefaultCellStyle.BackColor = Color.MistyRose;','Оформление строки не меняет Stock или Price у товара.',['DefaultCellStyle']],
 ['grid-zero-color','Нулевой остаток: ForeColor и BackColor','system.windows.forms.datagridviewcellstyle','Совмещает фон и цвет текста, чтобы отличать нулевой остаток от просто малого.','row.DefaultCellStyle.ForeColor = Color.DarkRed;','if (item.Stock == 0)\n{\n    row.DefaultCellStyle.BackColor = Color.MistyRose;\n    row.DefaultCellStyle.ForeColor = Color.DarkRed;\n}','Обычное выделение строки может временно показывать SelectionBackColor/SelectionForeColor вместо этих цветов.',['DefaultCellStyle.ForeColor']],
 ['cellformat','DataGridViewCellStyle.Format','system.windows.forms.datagridviewcellstyle.format','Форматирует показ значения ячейки без необходимости превращать исходное число в строку.','column.DefaultCellStyle.Format = "N2";','dgvProducts.Columns["Price"].DefaultCellStyle.Format = "N2";','Хранение decimal в ячейке лучше сохраняет числовую сортировку, чем заранее подготовленная строка с ₽.',['DefaultCellStyle.Format']],
 ['headertext','DataGridViewColumn.HeaderText','system.windows.forms.datagridviewcolumn.headertext','Видимый заголовок колонки. Он может отличаться от её программного Name.','column.HeaderText = "Заголовок";','dgvProducts.Columns["Stock"].HeaderText = "Остаток на складе";','При обращении Columns["Stock"] используется Name, а не русская надпись HeaderText.',['HeaderText']],
 ['datasource','DataGridView.DataSource','system.windows.forms.datagridview.datasource','Источник данных для связанной таблицы, например BindingList<Product> или BindingSource.','grid.DataSource = source;','BindingList<Product> products = new BindingList<Product>();\ndgvProducts.DataSource = products;','В таком режиме добавляйте объект в источник, а не через Rows.Add.',['DataSource']],
 ['autogeneratecolumns','DataGridView.AutoGenerateColumns','system.windows.forms.datagridview.autogeneratecolumns','Определяет, создавать ли колонки автоматически по свойствам связанного источника.','grid.AutoGenerateColumns = false;','dgvProducts.AutoGenerateColumns = false;\ndgvProducts.Columns["Name"].DataPropertyName = "Name";','Пример предполагает уже созданную колонку Name. При ручных колонках настройте DataPropertyName.',['AutoGenerateColumns','DataPropertyName']],
 ['selectionchanged','DataGridView.SelectionChanged','system.windows.forms.datagridview.selectionchanged','Срабатывает при изменении выделения. Используется для показа названия выбранного товара.','grid.SelectionChanged += handler;','private void dgvProducts_SelectionChanged(object sender, EventArgs e)\n{\n    lblSelectedProduct.Text = dgvProducts.CurrentRow?.Tag is Product item\n        ? item.Name : "Товар не выбран";\n}','Может возникать во время очистки и заполнения таблицы, когда CurrentRow или Tag ещё нет.',['SelectionChanged']],
 ['cellclick','DataGridView.CellClick','system.windows.forms.datagridview.cellclick','Возникает при щелчке ячейки. Аргументы события содержат индексы строки и колонки.','grid.CellClick += handler;','private void dgvProducts_CellClick(object sender, DataGridViewCellEventArgs e)\n{\n    if (e.RowIndex < 0) return;\n    lblOutput.Text = $"Строка: {e.RowIndex}";\n}','Индекс строки -1 соответствует заголовку; сначала отсеивайте такие щелчки.',['CellClick','RowIndex']],
 ['cellformatting','DataGridView.CellFormatting','system.windows.forms.datagridview.cellformatting','Позволяет настроить отображение ячейки во время её форматирования.','grid.CellFormatting += handler;','private void dgvProducts_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)\n{\n    if (e.Value is decimal value)\n    {\n        e.Value = value.ToString("N2");\n        e.FormattingApplied = true;\n    }\n}','Не добавляйте товары и не выполняйте долгие вычисления в событии отрисовки.',['CellFormatting','FormattingApplied']]
]);

add('Visual Studio','Команда редактора',[
 ['vs-properties','F4 — окно свойств',keyboard,'Открывает свойства выбранного компонента. В конструкторе позволяет менять Name, Text, Font и другие параметры.','F4','Выделите кнопку в конструкторе → F4 → (Name) = btnStart.','Сначала проверьте имя выбранного объекта над таблицей свойств. Клавиши зависят от профиля VS.',['F4']],
 ['vs-code','F7 — открыть код формы',keyboard,'Переключает выбранную форму на представление исходного кода.','F7','Откройте Form1.cs [Конструктор] → F7 → найдите обработчик Click.','Код поведения пишите в обычном .cs, а не заменяйте вручную .Designer.cs.',['F7']],
 ['vs-designer','Shift+F7 — открыть конструктор',keyboard,'Переключает документ на представление конструктора, если оно поддерживается.','Shift+F7','Откройте Form1.cs → Shift+F7.','У обычного класса Product нет конструктора формы: это не ошибка.',['Shift+F7','Shift + F7']],
 ['vs-toolbox','Ctrl+Alt+X — панель элементов',keyboard,'Открывает Toolbox для выбора компонентов активного конструктора.','Ctrl+Alt+X','Откройте конструктор формы → Ctrl+Alt+X → найдите Button.','Панель зависит от активного документа. В редакторе обычного класса набор компонентов может отсутствовать.',['Ctrl+Alt+X','Ctrl + Alt + X']],
 ['vs-run','Ctrl+F5 — запуск без отладки',keyboard,'Собирает и запускает проект без пошагового отладчика. В лекциях используется для проверки поведения формы.','Ctrl+F5','Сохраните проект → Ctrl+F5 → нажмите нужную кнопку в открывшемся приложении.','Если сборка не прошла, сначала исправьте ошибки; запуск старой успешной сборки не проверяет новый код.',['Ctrl+F5','Ctrl + F5']],
 ['vs-debug','F5 — запуск с отладкой',keyboard,'Запускает приложение с подключённым отладчиком или продолжает остановленное выполнение.','F5','Поставьте точку останова в обработчике → F5 → нажмите кнопку в форме.','Не путайте запуск с отладкой и Ctrl+F5 без отладки.',['F5']],
 ['vs-breakpoint','F9 — точка останова',keyboard,'Включает или убирает точку остановки на выполняемой строке.','F9','Выберите строку decimal total = price * quantity; → F9 → F5.','Точка должна стоять на исполняемом коде, а не на пустой строке или обычном комментарии.',['F9']],
 ['vs-stepover','F10 — шаг с обходом',keyboard,'Выполняет следующую команду. Вызванный метод обычно выполняется целиком без перехода в его тело.','F10','Остановитесь перед CalculateTotal(...) → F10 → посмотрите возвращённое значение.','Применяется во время остановки отладчика, а не вместо запуска программы.',['F10']],
 ['vs-stepinto','F11 — шаг с заходом',keyboard,'При пошаговой отладке позволяет перейти внутрь вызываемого метода, когда его код доступен отладчику.','F11','Остановитесь на item.TrySell(1) → F11 → пройдите проверки количества.','Настройки отладчика могут пропускать внешний библиотечный код.',['F11']],
 ['vs-stepout','Shift+F11 — выйти из метода',keyboard,'Продолжает выполнение до возвращения из текущего метода к вызывающему коду.','Shift+F11','Находясь внутри CalculateTotal, нажмите Shift+F11 и посмотрите итог у вызывающего метода.','Оставшиеся команды текущего метода выполнятся; они не пропускаются.',['Shift+F11']],
 ['vs-saveall','Ctrl+Shift+S — сохранить всё',keyboard,'Сохраняет изменённые документы решения перед сборкой, копированием или сдачей.','Ctrl+Shift+S','После изменения Product.cs и CatalogForm.cs нажмите Ctrl+Shift+S.','Сохранение не выполняет сборку и не доказывает правильность программы.',['Ctrl+Shift+S','Ctrl + Shift + S']],
 ['vs-build','Ctrl+Shift+B — собрать решение',keyboard,'Запускает сборку проектов решения и показывает ошибки компиляции.','Ctrl+Shift+B','Сохраните файлы → Ctrl+Shift+B → откройте «Список ошибок».','Успешная сборка подтверждает корректность компиляции, но не всех пользовательских сценариев.',['Ctrl+Shift+B','Ctrl + Shift + B']],
 ['vs-additem','Ctrl+Shift+A — добавить элемент',keyboard,'Открывает выбор нового файла проекта, например класса или формы.','Ctrl+Shift+A','Выберите проект → Ctrl+Shift+A → «Класс» → Product.cs.','Для карточки выбирайте «Форма Windows Forms», а не обычный класс без конструктора интерфейса.',['Ctrl+Shift+A','Ctrl + Shift + A']],
 ['vs-format','Ctrl+K, Ctrl+D — форматировать документ',keyboard,'Приводит отступы и оформление исходного документа к настройкам редактора.','Ctrl+K, Ctrl+D','Откройте .cs → нажмите Ctrl+K, отпустите → Ctrl+D.','Форматирование не исправляет алгоритм; незакрытые скобки сначала нужно восстановить.',['Ctrl+K, Ctrl+D','Ctrl+K Ctrl+D']],
 ['vs-errors','Список ошибок Visual Studio','https://learn.microsoft.com/en-us/visualstudio/ide/reference/error-list-window','Показывает ошибки, предупреждения и сообщения среды. Позволяет перейти к исходной строке.','Вид → Список ошибок','Начните с первой ошибки компилятора → двойной щелчок → проверьте указанную строку и предыдущую.','Одна отсутствующая скобка может вызвать много последующих ошибок; исправляйте причину по порядку.',['Список ошибок','Error List']],
 ['vs-designerfile','Form1.Designer.cs','https://learn.microsoft.com/en-us/dotnet/desktop/winforms/controls-design/designer-overview','Часть partial-класса формы с кодом, которым управляет визуальный конструктор.','partial class Form1','Form1.cs — код поведения.\nForm1.Designer.cs — создание и свойства компонентов.','Это пояснение структуры файлов, не код для вставки. Изменяйте интерфейс через конструктор; ручные правки Designer могут нарушить его работу.',['Designer.cs']],
 ['vs-watch','Окна Locals и Watch','https://learn.microsoft.com/en-us/visualstudio/debugger/watch-and-quickwatch-windows','Показывают значения переменных и выражений при остановке отладчика. Помогают проверить вычисления по шагам.','Отладка → Окна → Контрольные значения','На точке останова добавьте в Watch: requested, stock, requested > stock.','Выражения с вызовом методов могут иметь побочные эффекты; для начала наблюдайте простые значения.',['Watch','Locals','Контрольные значения','Локальные переменные']]
]);

add('Диалоги и приложение','Свойство или метод',[
 ['button-dialogresult','Button.DialogResult','system.windows.forms.button.dialogresult','Задаёт результат модальной формы при нажатии кнопки. Например, Cancel для отмены или OK для подтверждения.','button.DialogResult = DialogResult.OK;','btnClose.DialogResult = DialogResult.OK;','Это свойство кнопки, а результат после ShowDialog читает вызывающий код. В лекции №14 для btnClose предлагается DialogResult = OK в конструкторе.',['Button.DialogResult','btnClose.DialogResult','свойством DialogResult = OK']],
 ['messagebox','MessageBox.Show()','system.windows.forms.messagebox.show','Показывает стандартное модальное сообщение и возвращает выбранный пользователем DialogResult.','DialogResult result = MessageBox.Show(text);','MessageBox.Show(this, "Выберите товар", "Каталог",\n    MessageBoxButtons.OK, MessageBoxIcon.Information);','Окно сообщения не сохраняет данные и не завершает обработчик автоматически. После сообщения об ошибке часто нужен return.',['MessageBox.Show','MessageBox']],
 ['messagebox-buttons','MessageBoxButtons','system.windows.forms.messageboxbuttons','Набор кнопок стандартного диалога: OK, OKCancel, YesNo и другие комбинации.','MessageBoxButtons.YesNo','DialogResult answer = MessageBox.Show(\n    "Удалить товар?", "Подтверждение", MessageBoxButtons.YesNo);\nif (answer == DialogResult.Yes)\n    lblOutput.Text = "Удаление подтверждено";','Пример показывает только получение согласия. Удаление из _products и обновление таблицы пишутся отдельно.',['MessageBoxButtons','YesNo','OKCancel']],
 ['messagebox-icon','MessageBoxIcon','system.windows.forms.messageboxicon','Значок стандартного сообщения: Information, Warning, Error или Question. Помогает показать назначение диалога.','MessageBoxIcon.Warning','MessageBox.Show("Недостаточно товара", "Отказ",\n    MessageBoxButtons.OK, MessageBoxIcon.Warning);','Значок — оформление. Саму проверку остатка выполняет ваш код до изменения Stock.',['MessageBoxIcon']],
 ['openfiledialog','OpenFileDialog','system.windows.forms.openfiledialog','Стандартный диалог выбора существующего файла. После подтверждения путь доступен в FileName.','dialog.ShowDialog(owner)','using OpenFileDialog dialog = new OpenFileDialog();\ndialog.Filter = "Текстовые файлы (*.txt)|*.txt|Все файлы (*.*)|*.*";\nif (dialog.ShowDialog(this) == DialogResult.OK)\n    txtPath.Text = dialog.FileName;','Выбор файла ещё не читает его содержимое. Проверку существования, чтение и обработку ошибок выполняйте отдельно.',['OpenFileDialog','FileName']],
 ['savefiledialog','SaveFileDialog','system.windows.forms.savefiledialog','Диалог выбора имени и пути для сохраняемого файла. Возвращает путь, но не записывает содержимое автоматически.','dialog.ShowDialog(owner)','using SaveFileDialog dialog = new SaveFileDialog();\ndialog.Filter = "Текстовые файлы (*.txt)|*.txt";\ndialog.DefaultExt = "txt";\nif (dialog.ShowDialog(this) == DialogResult.OK)\n    txtPath.Text = dialog.FileName;','После OK нужно явно записать данные в выбранный файл. Сам диалог не создаёт отчёт.',['SaveFileDialog','DefaultExt']],
 ['tooltip','ToolTip.SetToolTip()','system.windows.forms.tooltip.settooltip','Связывает с элементом короткую подсказку, которая появляется при наведении указателя.','toolTip.SetToolTip(control, caption);','toolTip1.SetToolTip(nudSellQty,\n    "Количество должно быть больше 0 и не превышать остаток");','toolTip1 в примере — компонент ToolTip, добавленный на форму. Важные требования дублируйте обычным текстом рядом с полем.',['ToolTip','SetToolTip']],
 ['application-run','Application.Run()','system.windows.forms.application.run','Запускает цикл обработки сообщений интерфейса. Перегрузка с формой открывает главное окно приложения.','Application.Run(mainForm);','Application.Run(new CatalogForm());','Обычно уже находится в Program.cs. Не вызывайте повторно из Click, чтобы открыть карточку: для неё нужны Show или ShowDialog.',['Application.Run']],
 ['application-exit','Application.Exit()','system.windows.forms.application.exit','Просит завершить циклы сообщений приложения и закрыть его окна. Закрытие может быть отменено обработчиком FormClosing.','Application.Exit();','private void btnExit_Click(object sender, EventArgs e)\n{\n    Application.Exit();\n}','Для закрытия только карточки используйте Close() этой формы. Exit предназначен для завершения приложения целиком.',['Application.Exit']],
 ['application-init','ApplicationConfiguration.Initialize()','https://learn.microsoft.com/en-us/dotnet/core/compatibility/windows-forms/6.0/application-bootstrap','Настраивает стандартную конфигурацию запуска WinForms в современных шаблонах .NET. Код метода генерируется при сборке проекта.','ApplicationConfiguration.Initialize();','ApplicationConfiguration.Initialize();\nApplication.Run(new CatalogForm());','Используется в Program.cs современных проектов .NET 6+. Это генерируемый метод приложения; в старом .NET Framework шаблон и настройка запуска отличаются.',['ApplicationConfiguration','ApplicationConfiguration.Initialize']],
 ['begininvoke','Control.BeginInvoke()','system.windows.forms.control.begininvoke','Ставит выполнение делегата в очередь потока интерфейса и возвращает управление вызывающему потоку.','control.BeginInvoke(action);','lblOutput.BeginInvoke((Action)(() =>\n    lblOutput.Text = "Обновлено"));','В отличие от Invoke не ждёт окончания делегата. Нельзя планировать обновление уже уничтоженного окна; для нового кода .NET 9+ также изучите InvokeAsync.',['BeginInvoke']],
 ['checked','CheckBox.Checked','system.windows.forms.checkbox.checked','Состояние флажка: true, если он отмечен. Для трёх состояний есть отдельное CheckState.','bool selected = checkBox.Checked;','decimal discount = chkDiscount.Checked ? 10m : 0m;','Не сравнивайте Text флажка со строкой "true": подпись и состояние хранятся отдельно.',['Checked','CheckState']],
 ['key-down','Control.KeyDown','system.windows.forms.control.keydown','Событие нажатия клавиши, когда элемент получает клавиатурный ввод. Аргументы позволяют проверить клавишу и модификаторы.','control.KeyDown += handler;','private void txtArticle_KeyDown(object sender, KeyEventArgs e)\n{\n    if (e.KeyCode == Keys.Enter)\n    {\n        btnStart.PerformClick();\n        e.SuppressKeyPress = true;\n    }\n}','Обработчик надо связать с событием. Для обычной кнопки по Enter часто достаточно Form.AcceptButton.',['KeyDown','KeyEventArgs','Keys.Enter']]
]);

add('Учебный проект','Собственный класс или метод',[
 ['project-product','Product — класс товара',constructors,'Собственная модель учебного проекта. Объединяет название, производителя, категорию, цену, остаток и операции с ними.','Product item = new Product(...);','Product item = new Product(\n    "Кроссовки", "SportLine", "Спортивная", 4000m, 2);','Product не является встроенным классом .NET. Порядок параметров показан для модели из №11 и следующих работ; в №10 порядок отличается.',['Product']],
 ['project-product-ctor','Конструктор Product',constructors,'Получает начальные данные товара и проверяет допустимость цены и остатка при создании объекта.','public Product(string name, string manufacturer, string category, decimal price, int stock)','Product item = new Product(\n    "Ботинки", "NordStep", "Зимняя", 5200m, 7);','Это конструктор вашего класса. В №10 Category добавляется пятым параметром, а с №11 в новой версии модели стоит третьим. Сверяйте объявление именно своего Product.',['new Product','Product(']],
 ['project-name','Product.Name',properties,'Собственное строковое свойство названия товара. Не связано с техническим Name кнопки или формы.','public string Name { get; }','lblDetails.Text = $"Товар: {item.Name}";','В контролируемой модели значение назначается в конструкторе Product. Для поиска дубликатов проверяйте также производителя.',['Product.Name','public string Name','first.Name','item.Name','product.Name','existing.Name','selected.Name','У товара есть Name']],
 ['project-price','Product.Price',properties,'Собственное свойство модели — цена одной единицы товара, обычно decimal. В модели с проверками цена должна быть больше нуля.','public decimal Price { get; }','decimal lineTotal = item.Price * item.Stock;','Это цена одной единицы, а не общая стоимость всех остатков. Точный доступ к set определяется версией класса в лекции.',['Price']],
 ['project-stock','Product.Stock',properties,'Собственное свойство количества товара на складе. В модели с инкапсуляцией изменяется через проверяющие методы.','public int Stock { get; private set; }','if (!item.TrySell(1))\n    MessageBox.Show("Выдача невозможна");','При private set нельзя снаружи выполнять item.Stock = ...; используйте методы модели.',['Stock']],
 ['project-manufacturer','Product.Manufacturer',properties,'Собственное строковое свойство производителя товара. Вместе с названием участвует в проверке дубликатов.','public string Manufacturer { get; }','lblDetails.Text = $"Производитель: {item.Manufacturer}";','Совпадение только названия ещё не означает дубль, если производители разные.',['Manufacturer']],
 ['project-category','Product.Category',properties,'Собственное строковое свойство категории товара, например «Зимняя» или «Спортивная».','public string Category { get; }','lblDetails.Text = $"Категория: {item.Category}";','Не путайте свойство объекта со списком cmbCategory: интерфейс выбирает значение, модель его хранит.',['Category']],
 ['project-trysell','Product.TrySell()',methods,'Собственный метод выдачи со склада. Отклоняет неположительное количество или запрос больше остатка, при успехе уменьшает Stock.','bool TrySell(int quantity)','bool sold = item.TrySell(3);\nif (!sold)\n    lblOutput.Text = "Остаток не изменён";','Это не встроенная функция .NET. По договорённости учебного класса false означает отказ без изменения Stock.',['TrySell']],
 ['project-restock','Product.Restock()',methods,'Собственный метод пополнения склада положительным количеством. В версии из лекций возвращает bool.','bool Restock(int quantity)','bool added = item.Restock(4);\nlblOutput.Text = added ? "Добавлено" : "Количество неверно";','Это метод учебного Product. Отрицательное или нулевое количество не должно уменьшать складской остаток.',['Restock']],
 ['project-discount','Product.GetDiscountedPrice()',methods,'Собственный метод модели, возвращающий цену одной единицы после процентной скидки.','decimal GetDiscountedPrice(decimal percent)','decimal discounted = item.GetDiscountedPrice(10m);\nlblOutput.Text = $"{discounted:N2} ₽";','Это не стандартный метод decimal. Скидка 10% применяется к Price, а не к Stock; допустимый процент проверяется в вашей реализации.',['GetDiscountedPrice']],
 ['project-lowstock','Product.IsLowStock()',methods,'Собственный метод модели, отвечающий, является ли складской остаток малым. В лекциях граница обычно Stock <= 3.','bool IsLowStock()','if (item.IsLowStock())\n    row.DefaultCellStyle.BackColor = Color.MistyRose;','Это предметное правило учебного класса, а не встроенный метод числа. При Stock = 0 результат тоже true.',['IsLowStock']],
 ['project-refresh','RefreshProductsTable()',methods,'Собственный метод формы, который заново показывает текущую коллекцию товаров в таблице.','private void RefreshProductsTable()','_products.Add(item);\nRefreshProductsTable();','Не создавайте второй метод с тем же именем. Обновление должно читать существующие данные и не добавлять пять исходных товаров повторно.',['RefreshProductsTable']],
 ['project-calculate','CalculateTotal()',methods,'Собственный метод расчёта стоимости заказа с учётом количества и скидки. Помогает отделить вычисление от чтения полей.','decimal CalculateTotal(decimal price, int quantity, decimal discount)','decimal total = CalculateTotal(1000m, 2, 20m);\nlblTotal.Text = $"{total:N2} ₽";','Метод должен быть объявлен в вашем классе. Проверка допустимости заказа и остатка выполняется до успешного расчёта.',['CalculateTotal']],
 ['project-status','GetStockStatus()',methods,'Собственный метод из работы №8, который возвращает текст статуса по текущему остатку и запрошенному количеству.','string GetStockStatus(int stock, int requested)','string status = GetStockStatus(\n    (int)nudStock.Value, (int)nudQuantity.Value);\nlblStock.Text = status;','Порядок проверок в лекции: stock == 0; requested > stock; stock <= 3; иначе «В наличии». Метод только возвращает строку и не уменьшает остаток, в отличие от TrySell.',['GetStockStatus']],
 ['project-calculatediscount','CalculateDiscount()',methods,'Собственный метод расчёта суммы скидки в рублях. В дополнительном задании №8 его предлагают использовать рядом с CalculateTotal.','decimal CalculateDiscount(decimal subtotal, decimal percent)','private decimal CalculateDiscount(decimal subtotal, decimal percent)\n{\n    return subtotal * percent / 100m;\n}\n\n// В обработчике: CalculateDiscount(2000m, 20m) вернёт 400m.','Это учебный метод, который нужно объявить самостоятельно. Он возвращает именно сумму скидки, а не цену к оплате. Проверяйте допустимость исходной суммы и процента до расчёта.',['CalculateDiscount']],
 ['project-changeprice','Product.ChangePrice()',methods,'Собственный метод контролируемого изменения цены товара. Исходное дополнительное задание №11 требует запретить нулевую и отрицательную новую цену.','bool ChangePrice(decimal newPrice) // один из вариантов контракта','// Внутри Product; свойству Price нужен private set.\npublic bool ChangePrice(decimal newPrice)\n{\n    if (newPrice <= 0m) return false;\n    Price = newPrice;\n    return true;\n}','Это дополнительный пример: задание ChangePrice отсутствует в текущей отображаемой версии лекции. Исходник не задаёт возвращаемый тип; здесь выбран bool. При отказе цена остаётся прежней. Для Price только с get добавьте private set, не объявляя второе свойство.',['ChangePrice']],
 ['project-catalogform','CatalogForm',constructors,'Собственное окно каталога, где размещены список или таблица товаров и кнопки операций.','public partial class CatalogForm : Form','public CatalogForm()\n{\n    InitializeComponent();\n}','CatalogForm — имя учебного класса формы, а не отдельный стандартный элемент .NET.',['CatalogForm']],
 ['project-detailsform','ProductDetailsForm',constructors,'Собственная форма карточки. Получает выбранный Product через конструктор и показывает данные именно этого объекта.','new ProductDetailsForm(selected)','if (dgvProducts.CurrentRow?.Tag is Product selected)\n{\n    using ProductDetailsForm details = new ProductDetailsForm(selected);\n    details.ShowDialog(this);\n}','Сначала создайте эту форму в проекте. Передавайте выбранный объект, а не всегда первый товар списка.',['ProductDetailsForm']],
 ['project-tag-pattern','Связь строки с Product через Tag','system.windows.forms.datagridviewband.tag','При ручном заполнении таблицы связывает строку интерфейса с исходным товаром, чтобы затем открыть карточку или изменить остаток.','row.Tag = item;','int index = dgvProducts.Rows.Add(item.Name, item.Stock);\ndgvProducts.Rows[index].Tag = item;\n\nif (dgvProducts.CurrentRow?.Tag is Product selected)\n    lblSelectedProduct.Text = selected.Name;','Сохраняйте в Tag тот же экземпляр Product, который находится в _products. Иначе таблица и карточка могут показывать разное состояние.',['row.Tag','CurrentRow','Tag']]
]);

export const winformsEntries:HandbookEntry[]=entries;
